import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <class TA, class TB, class TC>
__global__ static void
triu_gemm_device(int M, int N, int K,
                  TA const* A, int ldA,
                  TB const* B, int ldB,
                  TC      * C, int ldC)
{
  int bm = blockIdx.x;
  int bn = blockIdx.y;

  const int TILE = 128;
  int row_start = bm * TILE;
  int col_start = bn * TILE;
  int row_end   = row_start + TILE - 1;
  int col_end   = col_start + TILE - 1;

  // Entire tile lies strictly below the diagonal -> output is all zero
  // (C was pre-zeroed on the host side), so we can skip it entirely.
  if (row_start > col_end) return;

  // Determine the useful K range for this tile:
  //   A(row,k) == 0 for k < row  => smallest needed k is row_start
  //   B(k,col) == 0 for k > col  => largest needed k is col_end
  int k_lo = row_start;                    // multiple of 8 since TILE % 8 == 0
  int k_hi = col_end + 1;
  if (k_hi > K) k_hi = K;
  int k_hi_aligned = ((k_hi + 7) / 8) * 8;
  if (k_hi_aligned > K) k_hi_aligned = K;

  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(ldA, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, ldB));
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(ldC, Int<1>{}));

  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<8>{});
  auto cta_coord = make_coord(bm, bn, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{});
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{});
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{});

  constexpr int SMEM_LD = 128 + 4; // pad shared-mem leading dimension (stride not multiple of 32) to reduce bank conflicts
  __shared__ TA smemA[SMEM_LD*8];
  __shared__ TB smemB[SMEM_LD*8];
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<128>{}, Int<8>{}), make_stride(Int<1>{}, Int<SMEM_LD>{}));
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<128>{}, Int<8>{}), make_stride(Int<1>{}, Int<SMEM_LD>{}));

  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}), make_stride(Int<8>{}, Int<1>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);

  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});

  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);

  int k_tile_start = k_lo / 8;
  int k_tile_end   = k_hi_aligned / 8; // exclusive

  for (int k_tile = k_tile_start; k_tile < k_tile_end; ++k_tile) {
    copy(tAgA(_,_,k_tile), tAsA);
    copy(tBgB(_,_,k_tile), tBsB);

    __syncthreads();

    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }

  // Epilogue: write back only the upper-triangular part (r <= c),
  // using an identity-coordinate tensor tiled the same way as gC.
  Tensor identity = make_identity_tensor(make_shape(M, N));
  Tensor cC  = local_tile(identity, cta_tiler, cta_coord, Step<_1,_1,X>{});
  Tensor tCcC = local_partition(cC, tC, threadIdx.x, Step<_1,_1>{});

  CUTE_UNROLL
  for (int i = 0; i < size(tCrC); ++i) {
    int r = get<0>(tCcC(i));
    int c = get<1>(tCcC(i));
    if (r <= c) {
      tCgC(i) = tCrC(i);
    }
  }
}

torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0) == K, "Inner dimensions must match");
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 8 == 0,
              "This kernel requires M,N multiple of 128 and K multiple of 8");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::zeros({M, N}, A.options());

  int ldA = K; // row-major (M,K)
  int ldB = N; // row-major (K,N)
  int ldC = N; // row-major (M,N)

  dim3 dimBlock(256);
  dim3 dimGrid(M / 128, N / 128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  triu_gemm_device<float,float,float><<<dimGrid, dimBlock, 0, stream>>>(
      M, N, K,
      A_c.data_ptr<float>(), ldA,
      B_c.data_ptr<float>(), ldB,
      C.data_ptr<float>(), ldC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triu_gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cutlass_triu = load_inline(
    name="cutlass_triu_matmul_inline",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


